package com.mauro.wgbg

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertNotNull
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File

/**
 * What a player has on their phone when an update arrives: saves, the remembered setup and online rooms as an older
 * release wrote them (app/src/test/resources/saves/<version>/, generated by that release's code). The update must
 * pick each one up as that release left it: 0.3.4 turned a 0.3.3 save's Orange player Purple mid-game.
 */
class OldSavesTest {
    private fun res(version: String, name: String) = File(javaClass.getResource("/saves/$version/$name")!!.toURI()).readText()

    /** expected.tsv: file, state hash, names by player, colours by player. */
    private fun expected(version: String) = res(version, "expected.tsv").lines().filter { it.isNotBlank() && !it.startsWith("#") }
        .map { it.split("\t") }

    @Test
    fun `a 0_3_3 local game resumes at the same position`() {
        for ((file, hash) in expected("0.3.3")) {
            val save = LocalSave.decode(res("0.3.3", file))
            assertNotNull(save, file)
            val state = save!!.replay()
            assertNotNull(state, "$file: a move no longer legal where it stands")
            assertFalse(state!!.isOver, file)
            assertEquals(hash.toLong(), state.stateHash(), "$file: the game the player left")
            assertTrue(save.resumable, file)
        }
    }

    @Test
    fun `a 0_3_3 local game keeps its players' names and colours`() {
        for ((file, _, names, colours) in expected("0.3.3")) {
            val save = LocalSave.decode(res("0.3.3", file))!!
            assertEquals(colours.split(","), save.setup.playerColours(save.seed).map { it.name }, "$file: colours by player")
            val you = names.split(",").first()
            assertEquals(names.split(","), save.setup.playerNames(you, save.seed), "$file: names by player")
        }
    }

    @Test
    fun `the setup 0_3_3 remembered comes back on the start screen`() {
        val s = GameSetup.decode(res("0.3.3", "setup-last.txt").trim())
        assertNotNull(s)
        assertEquals("Ann Marie", s!!.name)
        assertEquals(Ruleset.CHIVALRY, s.ruleset)
        assertEquals(12, s.points); assertEquals(3, s.decks)
        assertEquals(listOf(SeatKind.FRIEND, SeatKind.BOT, SeatKind.BOT, SeatKind.EMPTY), s.seats.take(4).map { it.kind })
    }

    @Test
    fun `a 0_3_3 room is refused with the update message, never misread`() {
        @Suppress("UNCHECKED_CAST")
        val doc = MiniJson.parse(res("0.3.3", "room-v2.json").trim()) as Map<String, Any?>
        val e = assertThrows(RoomVersionException::class.java) { room("ROVER-42", doc) }
        assertTrue(e.message!!.contains("older") && e.message!!.contains("update"), e.message)
    }
}
